require __DIR__.'/_admin.php';$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST') {admin_validate_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if(in_array($status,['new','contacted','quoted','closed'],true)){$q=$pdo->prepare('UPDATE quotations SET status=? WHERE id=?');$q->execute([$status,$id]);flash_set('Quotation status updated.');header('Location: quotes.php?id='.$id);exit;}}
if(isset($_GET['export'])&&$_GET['export']==='csv') {
 $rows=$pdo->query('SELECT reference,customer_name,phone,email,company,product,material,quantity,dimensions,printing,delivery_location,notes,status,created_at FROM quotations ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="ceylon-quotations-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");if($rows)fputcsv($out,array_keys($rows[0]));foreach($rows as $r){$safe=array_map(static function($v){$s=(string)$v;return preg_match('/^\s*[=+\-@]/u',$s)?"'".$s:$s;},$r);fputcsv($out,$safe);}fclose($out);exit;
}
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$one=null;if($id){$q=$pdo->prepare('SELECT * FROM quotations WHERE id=?');$q->execute([$id]);$one=$q->fetch();}
$rows=$pdo->query('SELECT id,reference,customer_name,phone,product,quantity,status,created_at FROM quotations ORDER BY id DESC')->fetchAll();
admin_header('Quotation Enquiries');flash_show();?><div class="panel"><div class="panel-header"><h2><?=$one?'Enquiry '.e($one['reference']):'All Enquiries'?></h2><div><a href="quotes.php?export=csv" class="admin-btn small">Export CSV ↓</a><?php if($one):?> <a href="quotes.php" class="admin-btn small light">← All Enquiries</a><?php endif;?></div></div>
<?php if($one):?><div class="quote-details"><dl><?php foreach(['reference'=>'Reference','customer_name'=>'Customer','phone'=>'Phone','email'=>'Email','company'=>'Company','product'=>'Product','material'=>'Material','quantity'=>'Quantity','dimensions'=>'Dimensions','printing'=>'Printing','delivery_location'=>'Delivery Location','notes'=>'Notes','created_at'=>'Received'] as $field=>$label):?><div><dt><?=e($label)?></dt><dd><?=nl2br(e((string)$one[$field]))?></dd></div><?php endforeach;?></dl><?php if($one['attachment_name']):?><p><a href="file.php?id=<?=(int)$one['id']?>" class="admin-btn small">Download Submitted Artwork ↓</a></p><?php endif;?><form method="post" class="status-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$one['id']?>"><label>Status <select name="status"><?php foreach(['new','contacted','quoted','closed'] as $s):?><option value="<?=e($s)?>" <?=$s===$one['status']?'selected':''?>><?=e(ucfirst($s))?></option><?php endforeach;?></select></label><button class="admin-btn small">Update Status</button></form></div>
<?php else:?><div class="table-scroll"><table><thead><tr><th>Reference</th><th>Customer</th><th>Phone</th><th>Product</th><th>Quantity</th><th>Status</th><th>Received</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="quotes.php?id=<?=(int)$r['id']?>" class="action-link"><?=e($r['reference'])?></a></td><td><?=e($r['customer_name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['product'])?></td><td><?=e($r['quantity'])?></td><td><span class="status-chip"><?=e($r['status'])?></span></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No quotation submissions received yet.</td></tr><?php endif;?></tbody></table></div><?php endif;?></div><?php admin_footer();?>
